				"yp-clean-side-guide": '\n        /* Clean side guide */\n        ytd-guide-section-renderer:has([title="YouTube Premium"]),\n        ytd-guide-renderer #footer {display: none !important;}\n        ytd-guide-section-renderer, ytd-guide-collapsible-section-entry-renderer {border: none !important;}\n      ',
