				openCommentsModal,
				closeCommentsModal,
				ensurePreviewFeature: async function ensurePreviewFeature(_features, signal) {
					return VotingApi.getPreviewFeature(signal);
				},
				getFacadeVoting: function getFacadeVoting() {
					return VotingSystem;
				},
				addCommentDraft: draft => {
					commentDrafts.push(draft), updateAttachmentStrip();
				},
				normalizeVoteType,
				renderSvgIcon,
				isCommunityWritable,
				isCommunityWriteEnabled,
				VotingApi,
				VotingMedia,
				VotingGallery,
